    point: `【Step 5・全コース 総復習】\nStep 1〜5 完全修了おめでとうございます！\n\n①Step 1：基礎会話（挨拶・数字・家族・趣味）\n②Step 2：実践会話（買い物・旅行・職場・健康）\n③Step 3：表現力（意見・提案・物語・交渉）\n④Step 4：応用（ビジネス・社会・文化・哲学）\n⑤Step 5：高度な言語運用（慣用句・討論・創作・抽象）\n\n한국어로 세상을 더 넓게 바라보세요！\n（韓国語でより広く世界を見渡してください！）`,
